package com.servicerca.controller;import com.servicerca.dto.media.MediaUploadResponse;import com.servicerca.security.SecurityUser;import com.servicerca.service.StorageService;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/files")public class MediaController{private final StorageService service;public MediaController(StorageService s){service=s;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ResponseEntity<MediaUploadResponse>upload(@AuthenticationPrincipal SecurityUser u,@RequestPart MultipartFile file){return ResponseEntity.status(201).body(service.upload(u.user(),file));}}
